const pageId = $('PrepGet').first().json.pageId;
const blocksResult = $input.first().json;
const blocks = (blocksResult.results || []).map(block => {
  const bType = block.type;
  let text = '';
  if (block[bType]?.rich_text) {
    text = block[bType].rich_text.map(t => t.plain_text).join('');
  } else if (bType === 'child_database') {
    text = '[child_database: ' + (block.child_database?.title || '') + ']';
  } else if (bType === 'image') {
    text = '[image]';
  } else if (bType === 'divider') {
    text = '---';
  }
  return { type: bType, text };
}).filter(b => b.text);
const textLines = blocks.map(b => b.text).join('\n');
return [{ json: {
  action: 'get',
  page_id: pageId,
  blocks: blocks,
  text_content: textLines
}}];

